#!/usr/bin/env node
/* Fit the rotation model from the shipped 2025-26 record, and write it down.
 *
 * WHY A GENERATED FILE RATHER THAN CONSTANTS IN THE MODULE. The same reason
 * data/model.js is generated: a coefficient typed into a function by hand is a
 * claim nobody can check, and it drifts from the evidence the moment the
 * evidence changes. This re-derives the numbers from the committed data every
 * time it runs, so the model and the season it came from cannot disagree.
 *
 * WHAT IS BEING FITTED. Changes to a club's starting eleven against its own
 * previous league match, explained by how much rest it has had:
 *
 *     expected changes = club baseline + rest effect + European away trip
 *
 * The club baseline carries most of the variation — Chelsea changed 3.27 a
 * match, Everton 1.57 — so the rest effect is measured as a RESIDUAL against
 * each club's own mean. Anything else would rediscover squad depth and call it
 * fatigue.
 *
 * The European increment is measured WITHIN the congested bucket, so a side
 * that flew back from an away leg on the Thursday is not counted twice.
 *
 *     node scripts/build-rotation-model.mjs
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import vm from 'node:vm';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const ctx = { console };
vm.createContext(ctx);
for (const f of ['assets/core.js', 'data/pl_other_fixtures_2526.js',
                 'data/pl_lineups_2526.js']) {
  vm.runInContext(readFileSync(join(root, 'data', '..', f), 'utf8'), ctx);
}
const C = vm.runInContext('PLDCore', ctx);
const OTHER = vm.runInContext('PL_OTHER_FIXTURES_2526', ctx);
const LINEUPS = vm.runInContext('PL_LINEUPS_2526', ctx);

/* Every competitive date per club: league kick-offs from the team sheets,
   which carry the REAL time, plus the cup and European ties. Synthesising a
   kick-off here would make a match its own predecessor for every evening
   fixture — it did, and it diluted the measured effect to a third of its
   true size before the bucket split gave it away. */
const dates = {}, xis = {};
for (const r of LINEUPS) (dates[r.c] = dates[r.c] || []).push({ d: r.d, comp: 'PL', v: '?' });
for (const e of OTHER) (dates[e.c] = dates[e.c] || []).push(e);
for (const r of [...LINEUPS].sort((a, b) => a.d.localeCompare(b.d))) {
  (xis[r.c] = xis[r.c] || []).push(r);
}

const rows = [];
for (const club of Object.keys(xis)) {
  const seq = xis[club];
  for (let i = 1; i < seq.length; i++) {
    const prev = new Set(seq[i - 1].xi);
    rows.push({
      club,
      changes: seq[i].xi.filter((n) => !prev.has(n)).length,
      bucket: C.restBucket(C.restDays(dates[club], seq[i].d)),
      euro: C.euroAway72h(dates[club], seq[i].d),
    });
  }
}

const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
const sd = (xs) => {
  const m = mean(xs);
  return Math.sqrt(xs.reduce((a, x) => a + (x - m) * (x - m), 0) / (xs.length - 1));
};
const round = (x) => Math.round(x * 1000) / 1000;

const clubMean = {};
for (const club of Object.keys(xis)) {
  clubMean[club] = mean(rows.filter((r) => r.club === club).map((r) => r.changes));
}
const resid = rows.map((r) => ({ ...r, e: r.changes - clubMean[r.club] }));

const rest = {};
for (const b of ['fresh', 'normal', 'congested']) {
  const xs = resid.filter((r) => r.bucket === b && !r.euro).map((r) => r.e);
  rest[b] = { n: xs.length, effect: round(mean(xs)) };
}
const ce = resid.filter((r) => r.bucket === 'congested' && r.euro).map((r) => r.e);
const cn = resid.filter((r) => r.bucket === 'congested' && !r.euro).map((r) => r.e);
const euroExtra = round(mean(ce) - mean(cn));

/* The headline the gate is judged on: does rest add anything ABOVE the club
   baseline? If it does not, this is squad depth wearing a fatigue label. */
const rf = resid.filter((r) => r.bucket === 'fresh').map((r) => r.e);
const rc = resid.filter((r) => r.bucket === 'congested').map((r) => r.e);
const lift = mean(rc) - mean(rf);
const se = Math.sqrt(sd(rc) ** 2 / rc.length + sd(rf) ** 2 / rf.length);

const out = {
  season: '2025-26',
  fitted: rows.length,
  leagueMean: round(mean(rows.map((r) => r.changes))),
  clubBaseline: Object.fromEntries(Object.entries(clubMean).map(([k, v]) => [k, round(v)])),
  rest: Object.fromEntries(Object.entries(rest).map(([k, v]) => [k, v.effect])),
  restSamples: Object.fromEntries(Object.entries(rest).map(([k, v]) => [k, v.n])),
  euroAwayExtra: euroExtra,
  lift: round(lift),
  liftSe: round(se),
  liftCi95: [round(lift - 1.96 * se), round(lift + 1.96 * se)],
  liftZ: round(lift / se),
};

const src = `// Auto-generated by scripts/build-rotation-model.mjs. Do not hand-edit.
//
// HOW MANY CHANGES A CLUB MAKES TO ITS STARTING ELEVEN, and how much of that
// is explained by rest. Fitted on ${out.fitted} team-fixtures of ${out.season}.
//
//   expected changes = clubBaseline[club] + rest[bucket] + euroAwayExtra
//
// The club baseline carries most of the variation (${Math.min(...Object.values(out.clubBaseline)).toFixed(2)} to ${Math.max(...Object.values(out.clubBaseline)).toFixed(2)} changes a
// match), so the rest effect is a RESIDUAL against each club's own mean —
// otherwise this would rediscover squad depth and call it fatigue. The
// European increment is measured WITHIN the congested bucket, so a side that
// flew home on the Thursday is not counted twice.
//
// LIFT ABOVE THE CLUB BASELINE: ${out.lift >= 0 ? '+' : ''}${out.lift} changes, 95% CI ${out.liftCi95[0]} to ${out.liftCi95[1]}, z = ${out.liftZ}.
// That is the number that says rest carries information a club average does
// not already have.
//
// NOT A CARD FACTOR. Rest days do not move a team's yellow count — the same
// season excludes an effect the size of the desk's 0.2 gate. This predicts
// TEAM SELECTION, which is a different question with a different answer.
const PL_ROTATION_MODEL = ${JSON.stringify(out, null, 2)};

if (typeof module !== 'undefined' && module.exports) module.exports = PL_ROTATION_MODEL;
`;

writeFileSync(join(root, 'data', 'rotation_model.js'), src, 'utf8');
console.log(`data/rotation_model.js written: fitted on ${out.fitted} team-fixtures, ` +
  `league mean ${out.leagueMean} changes; rest effect fresh ${out.rest.fresh}, ` +
  `normal ${out.rest.normal}, congested ${out.rest.congested}, ` +
  `European away extra ${out.euroAwayExtra}; lift ${out.lift} ` +
  `(CI ${out.liftCi95[0]} to ${out.liftCi95[1]}, z ${out.liftZ})`);
